import type { Register } from 'claude-code'

import { denyReason, findMatch, readSettings } from './rules'

export const register: Register = (on, options) => {
  const settings = readSettings(options)

  on('session.start', ($, e, next) => {
    if (settings.invalid.length > 0) {
      $.ui.toast(`${$.plugin.name}: ignored invalid regex in /config: ${settings.invalid.join(', ')}`)
    }
    return next(e)
  })

  on('tool.call', { tool: 'Bash' }, ($, e, next) => {
    const match = findMatch(e.command, settings)
    if (match === undefined) return next(e)

    if (settings.mode === 'warn') {
      $.ui.toast(`${$.plugin.name}: "${match.name}" is running (warn mode)`)
      return next(e)
    }

    $.ui.toast(`${$.plugin.name}: blocked "${match.name}"`)
    return { deny: denyReason($.plugin.name, match) }
  }).catch(($, e, next) =>
    next.called
      ? next(e)
      : { deny: `${$.plugin.name}: its check failed, so the command was not run to be safe.` },
  )
}

