{
  "name": "cm-block-dangerous-commands",
  "displayName": "Block Dangerous Commands",
  "version": "0.1.0",
  "description": "Refuses destructive Bash commands (rm -rf /, force-push to main, DROP TABLE, curl | sh, ...) before Claude runs them, and tells Claude why.",
  "author": {
    "name": "ClaudeMods",
    "url": "https://claudemods.app"
  },
  "homepage": "https://claudemods.app/mods/cm-block-dangerous-commands",
  "repository": "https://github.com/rotbit/claudemods-marketplace",
  "license": "MIT",
  "keywords": [
    "mod",
    "safety",
    "bash",
    "guard",
    "tool.call",
    "git",
    "rm"
  ],
  "userConfig": {
    "mode": {
      "type": "string",
      "title": "Mode",
      "description": "block refuses a matching command; warn lets it run and shows a toast.",
      "options": [
        "block",
        "warn"
      ],
      "default": "block"
    },
    "blockForcePush": {
      "type": "boolean",
      "title": "Block force-push to main/master",
      "description": "Refuse git push --force / -f / +main to main or master.",
      "default": true
    },
    "blockHardReset": {
      "type": "boolean",
      "title": "Block git reset --hard",
      "description": "Also refuse git reset --hard (off by default: it is a common, recoverable-ish workflow).",
      "default": false
    },
    "extraPatterns": {
      "type": "string",
      "title": "Extra patterns",
      "description": "Additional JavaScript regular expressions; a Bash command matching any of them is treated as dangerous.",
      "multiple": true,
      "default": []
    },
    "allowPatterns": {
      "type": "string",
      "title": "Allow patterns",
      "description": "JavaScript regular expressions; a Bash command matching any of them is never blocked, whatever else it matches.",
      "multiple": true,
      "default": []
    }
  }
}
